def blocks(k):
 s=texts[k]; out=[]
 for m in re.finditer(r'^\[([^\]]+)\][^\n]*\n',s,re.M):
  nxt=re.search(r'^\[',s[m.end():],re.M); end=m.end()+nxt.start() if nxt else len(s)
  raw=s[m.start():end]; fields=[]
  for line in raw.splitlines()[1:]:
   if re.match(r'^\w+\s*=',line):
    key,value=line.split('=',1);fields.append(dict(key=key.strip(),raw_value=value.strip()))
  out.append(dict(source_identity_key=k,header=m.group(1),range=[s.count('\n',0,m.start())+1,s.count('\n',0,end-1)+1],text=raw,ordered_raw_fields=fields,actual_reader=reader,meaning_credit='Complete raw record actually read; typed/default interpretation must use explicit common definitions, not this mechanical envelope.'))
 return out
def value(b,key):
 a=[f['raw_value'] for f in b['ordered_raw_fields'] if f['key']==key];return a[-1] if a else None
