mega=[b for b in forms if value(b,'MegaStone') is not None or value(b,'MegaMove') is not None]; needed={b['header'].split(',')[0] for b in forms}
base=[b for b in blocks('base') if b['header'] in needed]; stones={value(b,'MegaStone') for b in mega if value(b,'MegaStone')}; itemids=stones|{'MEGARING','REDORB','BLUEORB'}
items=[b for b in blocks('items') if b['header'] in itemids];moves=[b for b in blocks('moves') if b['header']=='DRAGONASCENT']
assert (len(forms),len(mega),len(base),len(stones),len(items),len(moves))==(50,48,48,47,50,1)
units=[]
def unit(k,name):
 s=texts[k];m=re.search(r'^( *)def '+re.escape(name)+r'(?=[( ;\n])[^\n]*\n',s,re.M);assert m,(k,name)
 end=m.end() if '; end' in m.group(0) else m.end()+re.search(r'^'+m.group(1)+r'end\s*$',s[m.end():],re.M).end()
 units.append(dict(id=k+':'+name,source_identity_key=k,range=[s.count('\n',0,m.start())+1,s.count('\n',0,end)+1],text=s[m.start():end],complete_definition=True));return k+':'+name
for n in ['getMegaForm','getUnmegaForm','hasMegaForm?','mega?','makeMega','makeUnmega','megaName','megaMessage','hasPrimalForm?','primal?','makePrimal','makeUnprimal']:unit('mega',n)
for n in ['species_data','species=','form','form_simple','form=','setForm','form_simple=','hp=','hasItem?','hasMove?','baseStats','calcIV','calcHP','calcStat','calc_stats']:unit('pokemon',n)
for n in ['self.get_species_form','initialize','default_form','base_form']:unit('species',n)
unit('compiler','validate_compiled_pokemon_form')
for n in ['self.call','self.getFunction','self.hasFunction?']:unit('handlers',n)
for spec in ['GROUDON','KYOGRE']:
 s=texts['handlers'];a=s.index('MultipleForms.register(:'+spec+',');z=s.index('\n})',a)+3;units.append(dict(id='handlers:'+spec,source_identity_key='handlers',range=[s.count('\n',0,a)+1,s.count('\n',0,z)+1],text=s[a:z],complete_registration=True))
fdata='deliverables/final-specification-set/pokemon-rules/wp22-transformation-data.md'; fmain='deliverables/final-specification-set/pokemon-rules/wp22-mega-and-primal-reversion.md'
table=[]; mismatches=[]
for line in (B/fdata).read_text().splitlines():
 m=re.match(r'\| ([A-Z]+) \| (\d+) \| (石 |已知招式 )([A-Z]+) \| ([0-9／]+) \|',line)
 if not m:continue
 species,form,kind,requirement,stats=m.groups(); key=species+','+form;b=next(x for x in mega if x['header']==key)
 got=value(b,'MegaStone' if kind=='石 ' else 'MegaMove');rawstats=value(b,'BaseStats').replace(',','／');ok=got==requirement and rawstats==stats
 table.append(dict(record=key,formal_requirement=requirement,raw_requirement=got,formal_six_stats=stats,raw_six_stats=rawstats,equal=ok))
 if not ok:mismatches.append(key)
