rows=[]
def add(label,needle,claims,refs,datarefs=None,formal=fmain):
 n=len(rows)+1;lines=[i+1 for i,l in enumerate((B/formal).read_text().splitlines()) if needle in l];assert lines,(label,needle)
 rows.append(dict(id=f'CTF-R{n:03}',label=label,formal=dict(path=formal,matching_lines=lines),premise='Fixed default top-level PBS only, valid ordinary persistent Pokemon/Species/Move/Item registries and required globals until stated failure. This context actually read every selected whole raw record and each definition below. Record field scan/arithmetic are static audit, not compiler or business execution.',child_assertions=[dict(id=f'CTF-R{n:03}-A{i:02}',meaning=c,source_units=refs,source_records=datarefs or [],status='BOUNDED_ACTUAL_SOURCE_DATA_SUPPORTED',whole_parent_acceptance=False) for i,c in enumerate(claims,1)],normal_cancel_failure='Queries can dereference/cache through their actual helpers but do not submit form. Ordered mutation prefixes remain if later handler, stats, dex, UI, localization or media raises; no transaction or compensation inferred. Malformed custom data stays distinct from these valid default records.',remaining='Full formal clauses, battle command/attack/switching, remaining PBS and host effects are separately reviewed; this group is not whole-domain acceptance.',accepted=False))
add('TARGET_SCAN','M01 目标选择',['Scan Species.each order; require same base species and data.unmega_form equals form_simple before checking item/move.','Stone present and exact persistent item match wins; otherwise move present and persistent known id match wins; two fields are alternatives.','First matching record breaks; ret starts zero. hasMegaForm requires ret>0 and differs from current simplified form.','No checks for egg/HP/Shadow/ring/quota/wild/PP/active item suppression in naked individual target definition.'],['mega:getMegaForm','mega:hasMegaForm?','pokemon:hasItem?','pokemon:hasMove?'])
add('DEFAULT48','48 个目标／46',['Actually read all 48 complete target records, 46 distinct Mega base species, 47 distinct stones plus Rayquaza DragonAscent. Table identities/target/six raw stats all48 equal; Slowbro target is2.','All48 omit UnmegaForm -> Species constructor default0; only Rayquaza writes MegaMessage1, allothers omitted->0. These are constructor defaults, not evidence of successful compilation.','Slowbro1 does not match default returnform0; Banette0+BANETTITE matches1, none/wrongitem matches0 under valid registry and no forced form.','Inherited omitted Abilities must come from matching complete base record through explicit form compiler collection clone gate; single printed ability name never implies all slots.'],['mega:getMegaForm','species:initialize','compiler:validate_compiled_pokemon_form'],[b['header'] for b in mega],fdata)
add('MEGA_IDENTITY','M02 当前 Mega 身份',['mega? asks current species_data mega_stone or mega_move truthiness; current held item or known move is not required.','getUnmegaForm returns current data.unmega_form when mega? else-1; makeMega submits only target>0 and makeUnmega only target>=0.','megaName uses translated nonempty form name else localized Mega base name; megaMessage asks newly selected target data, safe-navigation then ||0.','No default optional-set merging, ring, stat counter or battle-copy synchronization in individual methods.'],['mega:mega?','mega:getUnmegaForm','mega:makeMega','mega:makeUnmega','mega:megaName','mega:megaMessage','pokemon:species_data'])
add('FORCED_AND_FALLBACK','M03 查询不等于提交',['form_simple uses forced||stored: nil/false fall back, numeric0 is truthy; dynamic form getter instead honors any nonnil forced value including false.','Species.get_species_form parses symbols and returns base data when requested form missing; unknown species can still return nil then caller dereference fails.','form= writes stored, clears ability value cache only, calls onSetForm, calc_stats, then globalplayer dex register; repeated samevalue still calls.','setForm has optional yielded caller block between writes/cacheclear and handler; subsequent reentry can change actual stored form while handler receives original request.','species= same-base exits before forced/cache changes; newbase chooses default>=0 else target.form>0 else keeps oldstored; clears forced/conditionalgender/level/ability value, preserving ability_index.'],['pokemon:form_simple','pokemon:form','pokemon:form=','pokemon:setForm','pokemon:species=','species:self.get_species_form'])
add('RESOURCE_RAW','REDORB／BLUEORB 没有',['All47 selected stones have Pocket1 Price0 BPPrice50 and MegaStone,Fling_80 flags; none has a use entry in this record, and description does not confer battle permission.','REDORB and BLUEORB have Pocket1 Price10000 SellPrice0 BPPrice50, no MegaStone flag; their requirements come from Groudon/Kyogre callable.','MEGARING has Pocket8 Price0 flags KeyItem,MegaRing. Wholefile flag-field scan found exactly47 MegaStone lines and one MegaRing line; this is bounded flag-field inventory, not wholeitems semantic read.','DRAGONASCENT complete move is FLYING Physical120 Accuracy100 TotalPP5 NearOther LowerUserDefSpDef1 with Contact/CanProtect/CanMirrorMove/CannotMetronome; Mega only tests known id, so PP0 does not disqualify.'],['pokemon:hasItem?','pokemon:hasMove?','handlers:GROUDON','handlers:KYOGRE'],[b['header'] for b in items]+['DRAGONASCENT'],fdata)
add('PRIMAL_VALUES','P01 条件',['hasPrimalForm tests !nil; false and numeric0 are nonnil in definition and therefore satisfy presence test, without asserting a default such callable exists.','primal? requires returned nonnil and equality to raw stored @form, not form_simple/forced getter.','Default Groudon callable returns1 onlyhasItemREDORB else nil; Kyogre usesBLUEORB. Holding orb matches identity even under ordinarybattle item suppression because persistent helper is used.','makePrimal submits every nonnil return, unlike Mega>0. Default target1 records have HP100, Kyogre WATER/PRIMORDIALSEA and Groudon GROUND,FIRE/DESOLATELAND; correspondingbaseHP100.'],['mega:hasPrimalForm?','mega:primal?','mega:makePrimal','handlers:GROUDON','handlers:KYOGRE','pokemon:hasItem?'],['KYOGRE,1','GROUDON,1','KYOGRE','GROUDON'])
add('UNPRIMAL','P04 解除',['makeUnprimal first asks getUnprimalForm and submits nonnil return; onlyifnil asks primal? then submits0.','Entire actual FormHandlers source has no getUnprimalForm registration; source definition capability is still audited.','Removing orb through direct mutation can leave stored1 while primal?false, so nakedmakeUnprimal does not reset it; ordinary item-removal permission is separate consumer.','Explicit unmega/unprimal use ordinary form setter; neither returns battle quota, erases dex/stat history nor consumes item/PP.'],['mega:makeUnprimal','mega:primal?','handlers:self.call','pokemon:form='])
add('HP_VECTOR','前提：50 级',['48 complete target/base pairs show only METAGROSS,1 HP95 vsbase80; other47 equal. Fixed data retained rather than replaced by external franchise expectation.','calcHP atlevel50 IV0 EV0 gives base80 total140 andbase95 total155 using integer floor and +level+10.','calc_stats computes hp_difference, assigns newtotal first, then when oldHP>0 or difference>0 writes max(oldHP+difference,1) through hp= clamp and HP0 effects.','Current70 ->85 on Mega, back70 on解除; targetcurrent5->basecurrent1 when difference-15. LostHP difference preserved subject to floor, not HP percentage.','form_simple= onlywritesstored+calc, unlike form= cache/handler/dex; battle form write-through additionally invokes persistent setter. Stats are computed before later attack/defense writes; exceptions may leave a prefix.'],['pokemon:calcHP','pokemon:calc_stats','pokemon:hp=','pokemon:form=','pokemon:form_simple='],['METAGROSS','METAGROSS,1'],fdata)
